async function updateArtwork(track){const serial=++artworkSerial,source=safeCover(track?.cover);if(!source){applyArtwork({colors:[[48,54,64],[66,72,87],[34,39,48]],bitmap:''});return;}if(artworkCache.has(source)){applyArtwork(artworkCache.get(source));return;}try{const result=source.startsWith('data:')?{url:source}:await request('artwork',{cover:source}),img=new Image();img.src=result.url;await img.decode();const canvas=document.createElement('canvas');canvas.width=64;canvas.height=64;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(img,0,0,64,64);const colors=ArtworkColors.extract(context.getImageData(0,0,64,64).data),value={colors,bitmap:canvas.toDataURL('image/jpeg',.7)};if(artworkCache.size>=32)artworkCache.delete(artworkCache.keys().next().value);artworkCache.set(source,value);if(serial===artworkSerial)applyArtwork(value);}catch{if(serial===artworkSerial)applyArtwork({colors:[[48,54,64],[66,72,87],[34,39,48]],bitmap:''});}}
