async function request(name,data={}){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),55000);try{const r=await fetch('/api/'+name,{method:'POST',headers:{'Content-Type':'application/json','X-Local-Token':document.querySelector('meta[name=local-token]').content},body:JSON.stringify(data),signal:controller.signal});const body=await r.json();if(!r.ok||body.error)throw new Error(body.error||'请求失败，请重试');return body;}catch(e){if(e.name==='AbortError')throw new Error('连接超时，请检查网络后重试');if(e instanceof TypeError)throw new Error('本机服务连接中断，请重新打开播放器');throw e;}finally{clearTimeout(timeout);}}
