function albumFavoriteButton(album,retry){
  let subscribed=album.subscribed;
  const button=btn('',async()=>{
    if(!account.loggedIn){showLogin();return;}
    if(album.owner!==account.id||typeof subscribed!=='boolean'){retry();return;}
    if(button.disabled)return;
    const enabled=!subscribed,owner=account.id;button.disabled=true;button.textContent=enabled?'正在收藏…':'正在取消收藏…';
    try{
      const result=await request('album-favorite',{id:album.id,enabled,owner});
      if(account.id!==owner)return;
      if(result.owner!==owner||result.enabled!==enabled)throw new Error('专辑收藏更新未确认，请重试');
      subscribed=enabled;toast(enabled?'专辑已收藏':'已取消收藏专辑');
    }catch(error){if(account.id===owner)toast(error.message);}
    finally{render();}
  });
  function render(){button.disabled=false;button.textContent=typeof subscribed!=='boolean'?'重试收藏状态':subscribed?'取消收藏':'收藏专辑';button.title=typeof subscribed!=='boolean'?album.subscriptionError||'点击重新读取网易云收藏状态':'';if(typeof subscribed==='boolean')button.setAttribute('aria-pressed',String(subscribed));else button.removeAttribute('aria-pressed');}
  render();return button;
}
