async function toggle(){if(loadingPlayback)return;if(!current){if(queue.length)playTrack(queue[0]);else if(visibleSongs.length)playAll(visibleSongs);else toast('先搜索歌曲，或打开一个歌单。');return;}if(!audio.getAttribute('src')){playTrack(current,{position:restoredPosition});return;}if(audio.paused){try{await deck.resume();}catch(e){toast(e.message);}}else deck.pause();}
