async function toggleFavorite(track){if(!track){toast('选择歌曲后再收藏。');return;}const identity=key(track);if(heartPending.has(identity))return;if(track.source==='netease'){if(!account.loggedIn){showLogin();return;}if(cloudLikesStatus!=='ready'){if(await refreshCloudLikes(true))toast('红心已同步，请再次点击。');else toast(cloudLikesError);return;}}const enabled=!liked(track),owner=account.id;heartPending.add(identity);updateHearts();let success=false;try{const result=await request('favorite',{track,enabled});if(track.source==='netease'){if(account.id!==owner||result.owner!==owner)return;if(result.enabled!==enabled)throw new Error('网易云红心更新未确认，请重试');if(enabled)cloudLikeIds.add(track.id);else cloudLikeIds.delete(track.id);cloudLikesStatus='ready';heartSyncAt=Date.now();}else favorites=result.favorites;success=true;}catch(error){toast(error.message);}finally{heartPending.delete(identity);updateHearts();}if(success&&view==='favorites')await showFavorites(false,false);}
