function shortcutMessage(text,error=false){$('shortcutsStatus').textContent=text;$('shortcutsStatus').classList.toggle('error',error);}
function updateShortcutRuntime(state){if(!state)return;registeredShortcutKeys=new Set(Object.keys(state.registered||{}).filter(action=>state.registered[action]).map(action=>state.config[action]));}
function fillShortcutFields(config){$('shortcutsEnabled').checked=config.enabled;for(const field of document.querySelectorAll('[data-shortcut]')){field.dataset.accelerator=config[field.dataset.shortcut]||'';field.value=shortcutDisplay(field.dataset.accelerator);}}
function acceleratorFromEvent(event){const named={ArrowLeft:'Left',ArrowRight:'Right',ArrowUp:'Up',ArrowDown:'Down',Space:'Space',Home:'Home',End:'End',PageUp:'PageUp',PageDown:'PageDown',Insert:'Insert',Delete:'Delete'};let key=named[event.code];if(/^Key[A-Z]$/.test(event.code))key=event.code.slice(3);if(/^Digit[0-9]$/.test(event.code))key=event.code.slice(5);if(/^F([1-9]|1[0-9]|2[0-4])$/.test(event.code))key=event.code;if(!key)return null;const parts=[];if(event.ctrlKey)parts.push('Control');if(event.altKey)parts.push('Alt');if(event.shiftKey)parts.push('Shift');if(event.metaKey)parts.push('Super');if(!event.ctrlKey&&!event.altKey&&!event.metaKey&&!/^F[0-9]+$/.test(key))return null;return[...parts,key].join('+');}
async function showSettings(){$('playerLayoutSetting').value=settings.playerLayout||'split';$('lyricSizeSetting').value=String(settings.lyricSize);$('traySetting').checked=settings.closeToTray;$('crossfadeSetting').value=String(settings.crossfade??4);fillShortcutFields(settings.shortcuts||defaultShortcutConfig);shortcutMessage('');$('settingsDialog').showModal();if(!window.desktop){shortcutMessage('请在桌面播放器中设置全局快捷键。',true);return;}const state=await window.desktop.suspendShortcuts(true);updateShortcutRuntime(state);if(state?.config){fillShortcutFields(state.config);if(state.error)shortcutMessage(state.error,true);}}
$('settingsButton').onclick=()=>showSettings().catch(error=>shortcutMessage(error.message,true));
for(const field of document.querySelectorAll('[data-shortcut]'))field.addEventListener('keydown',event=>{if(event.code==='Tab')return;event.preventDefault();event.stopPropagation();if(event.code==='Escape'){field.blur();return;}const accelerator=acceleratorFromEvent(event);if(!accelerator){if(!['ControlLeft','ControlRight','AltLeft','AltRight','ShiftLeft','ShiftRight','MetaLeft','MetaRight'].includes(event.code))shortcutMessage('请按 Ctrl / Alt / Win 组合键，或 F1–F24。',true);return;}field.dataset.accelerator=accelerator;field.value=shortcutDisplay(accelerator);shortcutMessage('尚未保存');});
for(const button of document.querySelectorAll('[data-clear-shortcut]'))button.onclick=()=>{const field=document.querySelector('[data-shortcut="'+button.dataset.clearShortcut+'"]');field.dataset.accelerator='';field.value='未设置';shortcutMessage('尚未保存');};
$('shortcutDefaults').onclick=()=>{fillShortcutFields(defaultShortcutConfig);shortcutMessage('已恢复默认，点击保存后生效。');};
$('saveShortcuts').onclick=async()=>{if(!window.desktop)return;const config={enabled:$('shortcutsEnabled').checked};for(const field of document.querySelectorAll('[data-shortcut]'))config[field.dataset.shortcut]=field.dataset.accelerator||'';$('saveShortcuts').disabled=true;try{const result=await window.desktop.saveShortcuts(config);updateShortcutRuntime(result);if(!result.ok){shortcutMessage(result.error||'快捷键保存失败。',true);return;}settings.shortcuts=result.config;shortcutMessage(config.enabled?'已保存，关闭设置后全局生效。':'已保存，全局快捷键已关闭。');}catch(error){shortcutMessage(error.message,true);}finally{$('saveShortcuts').disabled=false;}};
$('settingsDialog').addEventListener('close',()=>{if(window.desktop)window.desktop.suspendShortcuts(false).then(result=>{updateShortcutRuntime(result);if(!result.ok)toast(result.error);}).catch(error=>toast(error.message));});
window.addEventListener('focus',()=>{if(!window.desktop)return;const pending=$('settingsDialog').open?window.desktop.suspendShortcuts(true):window.desktop.getShortcuts();pending.then(updateShortcutRuntime).catch(()=>{});});
$('qualitySetting').onchange=async event=>{deck.reset();const quality=event.target.value,position=audio.currentTime,autoplay=!audio.paused,active=current,hadSource=!!audio.getAttribute('src');$('qualitySetting').disabled=true;try{if(await saveSettings({quality})){if(active?.source==='netease'&&hadSource)await playTrack(active,{quality,position,autoplay});}}finally{$('qualitySetting').disabled=false;}};
$('playerLayoutSetting').onchange=event=>saveSettings({playerLayout:event.target.value});
$('lyricSizeSetting').onchange=async event=>{await saveSettings({lyricSize:Number(event.target.value)});lastLyric=-1;requestAnimationFrame(updateLyrics);};
