let nativeWindowState={fullscreen:false,maximized:false},topHideTimer,bottomHideTimer;
function immersivePlayer(){return !$('nowPanel').hidden&&(nativeWindowState.fullscreen||nativeWindowState.maximized);}
function syncScreenControls(){const immersive=immersivePlayer();document.querySelector('.topbar').inert=immersive&&!document.body.classList.contains('reveal-top');document.querySelector('.transport').inert=immersive&&!document.body.classList.contains('reveal-bottom');}
function hideScreenControls(){clearTimeout(topHideTimer);clearTimeout(bottomHideTimer);topHideTimer=bottomHideTimer=null;document.body.classList.remove('reveal-top','reveal-bottom');syncScreenControls();}
function applyWindowState(state){if(!state)return;nativeWindowState=state;document.body.classList.toggle('is-fullscreen',state.fullscreen);document.body.classList.toggle('is-maximized',state.maximized);document.body.classList.toggle('is-immersive',state.fullscreen||state.maximized);hideScreenControls();lastLyric=-1;requestAnimationFrame(updateLyrics);}
window.desktop?.onWindowState(applyWindowState);window.desktop?.getWindowState().then(applyWindowState).catch(()=>{});
function updateScreenControls(event){
  if(!immersivePlayer())return;
  const topbar=document.querySelector('.topbar'),transport=document.querySelector('.transport'),dragging=event.buttons>0;
  if(event.clientY<=8)document.body.classList.add('reveal-top');
  if(event.clientY>=innerHeight-8)document.body.classList.add('reveal-bottom');
  if(event.clientY<=topbar.offsetHeight||(dragging&&topbar.contains(event.target))){clearTimeout(topHideTimer);topHideTimer=null;}
  else if(document.body.classList.contains('reveal-top')&&!topHideTimer)topHideTimer=setTimeout(()=>{topHideTimer=null;document.body.classList.remove('reveal-top');syncScreenControls();},350);
  if(event.clientY>=innerHeight-transport.offsetHeight||(dragging&&transport.contains(event.target))){clearTimeout(bottomHideTimer);bottomHideTimer=null;}
  else if(document.body.classList.contains('reveal-bottom')&&!bottomHideTimer)bottomHideTimer=setTimeout(()=>{bottomHideTimer=null;document.body.classList.remove('reveal-bottom');syncScreenControls();},350);
  syncScreenControls();
}
document.addEventListener('mousemove',updateScreenControls);document.addEventListener('mouseup',updateScreenControls);
window.addEventListener('blur',hideScreenControls);
function setPlayerPage(open){$('nowPanel').hidden=!open;document.body.classList.toggle('player-open',open);hideScreenControls();$('mainContent').inert=open;document.querySelector('.sidebar').inert=open;$('lyricsButton').classList.toggle('active',open);if(open){$('settingsDialog').close();$('queueDialog').close();lastLyric=-1;requestAnimationFrame(()=>{updateLyrics();if(!immersivePlayer())$('closeLyrics').focus({preventScroll:true});});}else if(pageLoader&&!pageLoader.busy){pageLoader.observer.unobserve(pageLoader.node);pageLoader.observer.observe(pageLoader.node);}}
function toggleLyrics(){setPlayerPage($('nowPanel').hidden);}
$('lyricsButton').onclick=toggleLyrics;$('miniCover').onclick=toggleLyrics;$('trackName').onclick=toggleLyrics;$('closeLyrics').onclick=()=>{setPlayerPage(false);$('miniCover').focus({preventScroll:true});};
new ResizeObserver(()=>{if(!$('nowPanel').hidden){lastLyric=-1;updateLyrics();}}).observe($('lyrics'));

function renderQueue(){const list=$('queueList');list.replaceChildren();$('queueDescription').textContent=`${queue.length} 首歌曲 · ${$('mode').title}`;if(!queue.length){list.append(empty('队列是空的','从歌单播放，或把喜欢的歌曲加入这里。','list'));return;}for(const track of queue){const row=el('div',undefined,'queue-row'+(key(track)===key(current)?' current':'')),text=el('div',undefined,'queue-text');text.append(el('strong',track.name),el('small',track.artists));row.append(cover(track.cover),text);row.onclick=()=>{playTrack(track);$('queueDialog').close();setPlayerPage(true);};row.append(iconButton('close','从队列移除',event=>{event.stopPropagation();queue=queue.filter(t=>key(t)!==key(track));updateQueueCount();scheduleSave();renderQueue();}));list.append(row);}}
$('queueButton').onclick=()=>{renderQueue();$('queueDialog').showModal();};$('clearQueue').onclick=()=>{queue=[];updateQueueCount();scheduleSave();renderQueue();};
async function showLogin(){if($('loginDialog').open)return;$('loginDialog').showModal();$('logout').hidden=!account.loggedIn;$('loginTitle').textContent=account.loggedIn?'已连接 · '+account.nickname:'连接你的网易云';$('loginDescription').textContent=account.loggedIn?'重新扫码可以更换账号，当前登录凭证保存在本机。':'用网易云音乐 App 扫码，在手机上确认登录。';await generateQR();}
async function generateQR(){clearTimeout(qrTimer);const serial=++qrSerial;$('refreshQr').disabled=true;$('qrBox').replaceChildren(el('p','正在生成二维码…'));$('qrHint').textContent='';try{const result=await request('qr/start');if(serial!==qrSerial||!$('loginDialog').open)return;if(!/^data:image\/png;base64,/.test(result.image||''))throw new Error('二维码生成失败，请重试');const img=el('img');img.src=result.image;img.alt='网易云登录二维码';$('qrBox').replaceChildren(img);$('qrHint').textContent='使用网易云 App 扫码确认';const start=Date.now();async function poll(){if(serial!==qrSerial||!$('loginDialog').open)return;if(Date.now()-start>180000){$('qrHint').textContent='二维码已过期，请刷新';return;}try{const status=await request('qr/check');if(serial!==qrSerial||!$('loginDialog').open)return;if(status.code===803){account=status.account;heartRefreshPromise=null;cloudLikeIds=new Set();cloudLikesStatus='loading';renderAccount();$('loginDialog').close();toast('网易云账号已连接');await refreshCloudLikes(true);showStartPage();return;}if(status.code===800){$('qrHint').textContent='二维码已过期，请刷新';return;}$('qrHint').textContent=status.code===802?'已扫码，等待手机确认':'等待扫码';qrTimer=setTimeout(poll,2200);}catch(e){$('qrHint').textContent=e.message+'；请刷新二维码';}}qrTimer=setTimeout(poll,1500);}catch(e){$('qrBox').replaceChildren(el('p',e.message));}finally{$('refreshQr').disabled=false;}}
$('accountButton').onclick=showLogin;$('refreshQr').onclick=generateQR;$('loginDialog').addEventListener('close',()=>{qrSerial++;clearTimeout(qrTimer);});
$('logout').onclick=async()=>{try{await request('logout');account={loggedIn:false};applyCloudLikes({status:'signedout',ids:[]});homeData.playlists=[];deck.reset();audio.pause();audio.removeAttribute('src');audio.load();playInfo=null;renderAccount();renderSidebar();$('loginDialog').close();toast('已清除播放器内的登录凭证。');showStartPage();}catch(e){toast(e.message);}};
async function importLocal(){if(!window.desktop){toast('请通过“启动VESPER”打开桌面播放器后导入。');return;}try{const result=await window.desktop.importAudio();if(result.canceled)return;localSongs=result.songs;toast(`已导入 ${result.added} 首${result.errors.length?'；'+result.errors.length+' 个文件未能读取':''}`);showList('local');}catch(e){toast('导入失败：'+e.message);}}
$('importPlaylist').onclick=()=>$('linkDialog').showModal();$('playlistForm').onsubmit=event=>{event.preventDefault();const input=$('playlistInput').value.trim();if(!input)return;$('linkDialog').close();loadPlaylist(input);};
$('searchForm').onsubmit=event=>{event.preventDefault();search();};
