for(const node of document.querySelectorAll('[data-view]'))node.onclick=()=>['subscribed-albums','followed-artists'].includes(node.dataset.view)?showCollection(node.dataset.view):showList(node.dataset.view);
for(const node of document.querySelectorAll('[data-close-dialog]'))node.onclick=()=>$(node.dataset.closeDialog).close();
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
for(const button of document.querySelectorAll('[data-window]'))button.onclick=()=>window.desktop?.control(button.dataset.window);
