window.desktop?.onMedia(action=>{if(action==='toggle')toggle();if(action==='next')next(true);if(action==='previous')previous();});
document.addEventListener('keydown',event=>{if(event.code==='F11'&&!document.querySelector('dialog[open]')){event.preventDefault();window.desktop?.control('fullscreen');return;}if(event.code==='Escape'&&nativeWindowState.fullscreen&&!document.querySelector('dialog[open]')){event.preventDefault();window.desktop?.control('fullscreen');return;}if(['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)||document.querySelector('dialog[open]'))return;if(registeredShortcutKeys.has(acceleratorFromEvent(event)))return;if(event.code==='Escape'&&!$('nowPanel').hidden){setPlayerPage(false);return;}if(event.code==='Space'&&!event.ctrlKey&&!event.altKey&&!event.metaKey&&!event.shiftKey){event.preventDefault();toggle();}if(event.ctrlKey&&!event.altKey&&!event.metaKey&&!event.shiftKey&&event.code==='ArrowRight'){event.preventDefault();next(true);}if(event.ctrlKey&&!event.altKey&&!event.metaKey&&!event.shiftKey&&event.code==='ArrowLeft'){event.preventDefault();previous();}});
if('mediaSession'in navigator){for(const [name,handler]of Object.entries({play:()=>audio.getAttribute('src')?deck.resume():toggle(),pause:()=>deck.pause(),previoustrack:previous,nexttrack:()=>next(true),seekto:details=>{if(Number.isFinite(audio.duration)&&Number.isFinite(details.seekTime)){deck.seek();audio.currentTime=Math.min(audio.duration,details.seekTime);}}}))try{navigator.mediaSession.setActionHandler(name,handler);}catch{}}
