(async()=>{replaceCover($('nowCover'),'');replaceCover($('miniCover'),'');$('view').replaceChildren(loading());try{const data=await request('bootstrap');account=data.account;settings=data.settings;favorites=data.favorites;applyCloudLikes(data.cloudLikes);localSongs=data.local;queue=data.state.queue||[];current=queue.find(t=>key(t)===data.state.current)||null;shuffleOrder.restore(data.state.shuffle,queue.map(key),key(current));restoredPosition=data.state.position||0;if(current?.source==='netease'&&!current.cover){try{const detail=await request('song',{input:current.id});Object.assign(current,detail);}catch{}}applySettings();window.desktop?.getShortcuts().then(updateShortcutRuntime).catch(()=>{});renderAccount();updateQueueCount();updateCurrentUI();updatePlaybackUI();if(current){setQualityInfo('已记住上次进度');$('elapsed').textContent=time(restoredPosition);$('duration').textContent=time(current.duration/1000);const progress=current.duration?Math.min(100,restoredPosition/(current.duration/1000)*100):0;$('seek').value=progress*10;$('seek').style.background=`linear-gradient(to right,var(--accent) ${progress}%,var(--line) 0%)`;loadLyrics(current,playSerial);}if(data.warning)toast(data.warning,8000);await showStartPage();}catch(e){showError(e,()=>location.reload());}})();
